/** Job types, public serialization, and submission validation shared by the server and worker. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

/** Row shape of the `jobs` table as returned by node:sqlite. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The public job shape returned by every job-returning endpoint. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? (row.error ?? TRANSIENT_ERROR) : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

export type Validation =
  | { ok: true; payload: Payload; idempotencyKey: string | null }
  | { ok: false; fields: FieldError[] };

/** True for `application/json`, case-insensitively, optionally followed by parameters. */
export function isJsonContentType(value: string | undefined): boolean {
  if (value === undefined) return false;
  return value.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

const isInt = (v: unknown, min: number, max: number): v is number =>
  typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;

/**
 * Validates a submission completely before any database change. Collects every discoverable
 * offending field instead of stopping at the first.
 */
export function validateSubmission(req: {
  contentType: string | undefined;
  body: string;
  tooLarge: boolean;
  idempotencyKey: string | undefined;
}): Validation {
  const fields: FieldError[] = [];

  if (req.idempotencyKey !== undefined && !KEY_PATTERN.test(req.idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must be 1–128 characters of letters, digits, "_" or "-".' });
  }

  const fail = (): Validation => ({ ok: false, fields });

  if (!isJsonContentType(req.contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    return fail();
  }
  if (req.tooLarge) {
    fields.push({ field: 'body', message: 'Request body is too large.' });
    return fail();
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(req.body);
  } catch {
    fields.push({ field: 'body', message: 'Request body must be valid JSON.' });
    return fail();
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'Request body must be a JSON object.' });
    return fail();
  }

  const obj = parsed as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'Required.' });
  } else {
    const v = obj.input;
    if (typeof v !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else if (v.length < 1 || v.length > 1000) fields.push({ field: 'input', message: 'Must be 1–1000 characters.' });
    else if (v.trim() === '') fields.push({ field: 'input', message: 'Must not be only whitespace.' });
    else input = v;
  }

  let steps = 5;
  if (Object.hasOwn(obj, 'steps')) {
    if (isInt(obj.steps, 1, 20)) steps = obj.steps;
    else fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  }

  let failAttempts = 0;
  if (Object.hasOwn(obj, 'failAttempts')) {
    if (isInt(obj.failAttempts, 0, 5)) failAttempts = obj.failAttempts;
    else fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  }

  if (fields.length > 0) return fail();
  return {
    ok: true,
    payload: { input, steps, failAttempts },
    idempotencyKey: req.idempotencyKey ?? null,
  };
}

