import { DatabaseSync, type StatementSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';
import { toJob, type Job, type JobRow, type Payload } from './jobs.ts';

/** A worker heartbeat older than this means the worker is down. */
export const HEARTBEAT_STALE_MS = 3_000;

/** Opens the SQLite database shared by the server and worker processes and makes sure the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  initSchema(db);
  return db;
}

/** Idempotent: either process may create the schema first. */
export function initSchema(db: DatabaseSync): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0,
      output TEXT,
      error TEXT,
      idempotency_key TEXT UNIQUE,
      available_at INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
    CREATE TABLE IF NOT EXISTS worker_state (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      heartbeat_at INTEGER NOT NULL
    );
  `);
}

/** Runs `fn` inside a short IMMEDIATE transaction. `fn` must be synchronous. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction open
    }
    throw e;
  }
  return result;
}

const SQL = {
  insert: `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, available_at, created_at, updated_at)
           VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  byId: 'SELECT * FROM jobs WHERE id = ?',
  bySeq: 'SELECT * FROM jobs WHERE seq = ?',
  byKey: 'SELECT * FROM jobs WHERE idempotency_key = ?',
  list: 'SELECT * FROM jobs ORDER BY seq DESC',
  findRunning: "SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1",
  findQueued: "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1",
  markRunning: `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL, updated_at = ?
                WHERE seq = ?`,
  resetRunning: "UPDATE jobs SET completed = 0, updated_at = ? WHERE seq = ? AND status = 'running'",
  progress: "UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ? AND status = 'running' AND attempts = ?",
  complete: `UPDATE jobs SET completed = steps, status = 'completed', output = ?, updated_at = ?
             WHERE seq = ? AND status = 'running' AND attempts = ?`,
  retry: `UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ?
          WHERE seq = ? AND status = 'running' AND attempts = ?`,
  fail: `UPDATE jobs SET status = 'failed', completed = 0, error = 'transient failure', updated_at = ?
         WHERE seq = ? AND status = 'running' AND attempts = ?`,
  heartbeatWrite: `INSERT INTO worker_state (id, heartbeat_at) VALUES (1, ?)
                   ON CONFLICT (id) DO UPDATE SET heartbeat_at = excluded.heartbeat_at`,
  heartbeatRead: 'SELECT heartbeat_at FROM worker_state WHERE id = 1',
  heartbeatClear: 'DELETE FROM worker_state WHERE id = 1',
} as const;

export type CreateOutcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/** All reads and writes of the jobs table, shared by the server and the worker. */
export class Store {
  readonly db: DatabaseSync;
  private readonly stmts: Record<keyof typeof SQL, StatementSync>;

  constructor(db: DatabaseSync) {
    this.db = db;
    const stmts = {} as Record<keyof typeof SQL, StatementSync>;
    for (const name of Object.keys(SQL) as (keyof typeof SQL)[]) stmts[name] = db.prepare(SQL[name]);
    this.stmts = stmts;
  }

  /**
   * Creates a job, or resolves an idempotent submission. The key lookup and insert share one
   * IMMEDIATE transaction, and the UNIQUE constraint on idempotency_key backs it up.
   */
  createJob(payload: Payload, idempotencyKey: string | null): CreateOutcome {
    return transaction(this.db, () => {
      if (idempotencyKey !== null) {
        const existing = this.stmts.byKey.get(idempotencyKey) as unknown as JobRow | undefined;
        if (existing) {
          const same =
            existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
          return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
        }
      }
      const now = new Date().toISOString();
      const id = randomUUID();
      this.stmts.insert.run(id, payload.input, payload.steps, payload.failAttempts, idempotencyKey, now, now);
      const row = this.stmts.byId.get(id) as unknown as JobRow;
      return { kind: 'created', job: toJob(row) };
    });
  }

  listJobs(): Job[] {
    return (this.stmts.list.all() as unknown as JobRow[]).map(toJob);
  }

  getJob(id: string): Job | undefined {
    const row = this.stmts.byId.get(id) as unknown as JobRow | undefined;
    return row ? toJob(row) : undefined;
  }

  /** Claims the next attempt. An interrupted running job is replayed first, keeping its attempt number. */
  claimNext(now: number = Date.now()): JobRow | undefined {
    return transaction(this.db, () => {
      const iso = new Date().toISOString();
      const running = this.stmts.findRunning.get() as unknown as JobRow | undefined;
      if (running) {
        this.stmts.resetRunning.run(iso, running.seq);
      } else {
        const queued = this.stmts.findQueued.get(now) as unknown as JobRow | undefined;
        if (!queued) return undefined;
        this.stmts.markRunning.run(iso, queued.seq);
      }
      const seq = running?.seq ?? (this.stmts.findRunning.get() as unknown as JobRow | undefined)?.seq;
      return seq === undefined ? undefined : (this.stmts.bySeq.get(seq) as unknown as JobRow);
    });
  }

  recordProgress(seq: number, attempt: number, completed: number): void {
    this.stmts.progress.run(completed, new Date().toISOString(), seq, attempt);
  }

  completeAttempt(seq: number, attempt: number, output: string): void {
    this.stmts.complete.run(output, new Date().toISOString(), seq, attempt);
  }

  scheduleRetry(seq: number, attempt: number, availableAt: number): void {
    const iso = new Date().toISOString();
    this.stmts.retry.run(availableAt, iso, seq, attempt);
  }

  failAttempt(seq: number, attempt: number): void {
    this.stmts.fail.run(new Date().toISOString(), seq, attempt);
  }

  heartbeat(now: number = Date.now()): void {
    this.stmts.heartbeatWrite.run(now);
  }

  clearHeartbeat(): void {
    this.stmts.heartbeatClear.run();
  }

  workerUp(now: number = Date.now()): boolean {
    const row = this.stmts.heartbeatRead.get() as { heartbeat_at: number } | undefined;
    return row !== undefined && now - row.heartbeat_at <= HEARTBEAT_STALE_MS;
  }
}

