    this.stmts.complete.run(output, new Date().toISOString(), seq, attempt);
  }

  scheduleRetry(seq: number, attempt: number, availableAt: number): void {
    const iso = new Date().toISOString();
    this.stmts.retry.run(availableAt, iso, seq, attempt);
  }

  failAttempt(seq: number, attempt: number): void {
    this.stmts.fail.run(new Date().toISOString(), seq, attempt);
  }

  heartbeat(now: number = Date.now()): void {
    this.stmts.heartbeatWrite.run(now);
  }

  clearHeartbeat(): void {
    this.stmts.heartbeatClear.run();
  }

  workerUp(now: number = Date.now()): boolean {
    const row = this.stmts.heartbeatRead.get() as { heartbeat_at: number } | undefined;
    return row !== undefined && now - row.heartbeat_at <= HEARTBEAT_STALE_MS;
  }
