import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, Store } from './db.ts';
import { validateSubmission, type FieldError } from './jobs.ts';

const db = openDatabase();
const store = new Store(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const MAX_BODY_BYTES = 64 * 1024;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

function send(res: ServerResponse, status: number, body: unknown, extra: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extra });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function notAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allowed.join(', ')}.`).valueOf;
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  send(res, 405, { error: { code: 'method_not_allowed', message: `Method not allowed. Use ${allowed.join(', ')}.` } }, {
    allow: allowed.join(', '),
  });
}

async function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  const chunks: Buffer[] = [];
  let size = 0;
  let tooLarge = false;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > MAX_BODY_BYTES) {
      tooLarge = true;
      continue;
    }
    chunks.push(buf);
  }
  return { text: Buffer.concat(chunks).toString('utf8'), tooLarge };
}

function header(req: IncomingMessage, name: string): string | undefined {
  const v = req.headers[name];
  return Array.isArray(v) ? v.join(', ') : v;
}

async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const v = validateSubmission({
    contentType: header(req, 'content-type'),
    body: text,
    tooLarge,
    idempotencyKey: header(req, 'idempotency-key'),
  });
  if (!v.ok) {
    const names = v.fields.map((f) => f.field).join(', ');
    return sendError(res, 400, 'invalid_request', `Invalid request: ${names}.`, v.fields);
  }
  const outcome = store.createJob(v.payload, v.idempotencyKey);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? '';

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return send(res, 200, { status: 'ok', worker: store.workerUp() ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: store.listJobs() });
    if (method === 'POST') return createJobRoute(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const job = store.getJob(match[1]!);
    if (!job) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else if (!res.writableEnded) res.end();
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Stop accepting connections; idle keep-alive sockets are closed right away. Handlers are
  // synchronous around the database, so once close() fires no database user is outstanding.
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 2_000).unref();
  setTimeout(() => {
    db.close();
    process.exit(0);
  }, 5_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

