import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, Store } from './db.ts';
import { MAX_ATTEMPTS, type JobRow } from './jobs.ts';

const HEARTBEAT_MS = 500;
const POLL_MS = 100;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
const store = new Store(db);
let stopping = false;
const stopController = new AbortController();

/** Waits for `ms`, or returns early when shutdown begins. */
async function pause(ms: number): Promise<void> {
  try {
    await sleep(ms, undefined, { signal: stopController.signal });
  } catch {
    // aborted by shutdown
  }
}

/**
 * Runs one attempt of a job. The attempt number is fixed by the claim, so a replayed attempt that
 * was interrupted by a crash fails or completes under the same rules as the original.
 */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  const failing = attempt <= job.fail_attempts;
  for (let step = 1; step <= job.steps; step++) {
    await pause(STEP_MS);
    if (stopping) return;

    if (step === 1 && failing) {
      if (attempt < MAX_ATTEMPTS) store.scheduleRetry(job.seq, attempt, Date.now() + RETRY_DELAY_MS);
      else store.failAttempt(job.seq, attempt);
      return;
    }

    if (step === job.steps) store.completeAttempt(job.seq, attempt, job.input.toUpperCase());
    else store.recordProgress(job.seq, attempt, step);
  }
}

async function loop(): Promise<void> {
  while (!stopping) {
    try {
      const job = store.claimNext();
      if (!job) {
        await pause(POLL_MS);
        continue;
      }
      await runAttempt(job);
    } catch (err) {
      console.error('worker iteration failed:', err);
      await pause(RETRY_DELAY_MS);
    }
  }
}

function beat(): void {
  try {
    store.heartbeat();
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

function shutdown(): void {
  if (stopping) return;
  stopping = true;
  stopController.abort();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);
console.log('worker started');
await loop();

clearInterval(heartbeatTimer);
try {
  store.clearHeartbeat();
} catch {
  // best effort; the heartbeat goes stale anyway
}
db.close();
console.log('worker stopped');

